// :mega: forwarder, step 1 (n8n Code node). Input: conversations.history for #revtech-status.
// Finds messages newly reacted with :mega:, strips the alert text, and builds the Anthropic
// request body that turns the raw alert into a customer-friendly #sf-help notice in Paul's voice.
const store = (typeof $getWorkflowStaticData === 'function') ? $getWorkflowStaticData('global') : this.getWorkflowStaticData('global');
store.fwd = store.fwd || {};
const resp = $input.first() ? $input.first().json : {};
if (resp && resp.ok === false) {
  throw new Error('Slack conversations.history failed: ' + (resp.error || 'unknown') + (resp.needed ? ' (needed scope: ' + resp.needed + ')' : ''));
}

const SYSTEM = [
  "You write short service-status notices for Point of Rental's #sf-help Slack channel, where reps and staff watch for vendor issues that affect their work.",
  "Input: a raw internal monitoring alert about a third-party vendor (Salesforce, Gong, Zoom, Google Workspace, AWS, etc.). Rewrite it as a clear, calm notice for staff, in Slack mrkdwn.",
  "",
  "Mirror this real example exactly in shape:",
  ":warning: *Known Issue: Gong not recording Google Meet calls*",
  "",
  "Gong has an open incident affecting Google Meet call recording. Some calls are not being recorded or transcribed while this is active.",
  "",
  "This is on Gong's side, not a Salesforce or POR configuration issue.",
  "",
  "Track status here: <https://status.gong.io/|Gong status>",
  "",
  "If this is impacting you, submit a ticket at Helpdesk.pointofrental.com",
  "",
  "Rules:",
  "- Lead with an emoji + bold title naming the vendor and the impact (:warning: for outage/degradation, :white_check_mark: for restored).",
  "- 1 to 2 short, plain-English sentences on what is happening and what it affects.",
  "- If it is the vendor's fault, say it is on their side, not a POR or Salesforce config issue.",
  "- Include the status link if one is provided, as a Slack link <url|label>.",
  "- Close with: If this is impacting you, submit a ticket at Helpdesk.pointofrental.com",
  "- Voice: friendly, direct, warm, not formal. Short declarative sentences. One idea per line, blank line between lines. State things flatly, no hedging.",
  "- NO em dashes. Avoid the words: dive into, leverage, straightforward, circle back.",
  "- Do not invent details, root causes, or resolution times that are not in the alert.",
  "- Output ONLY the notice text in Slack mrkdwn. No preamble, no 'here is'.",
].join('\n');

const msgs = (resp && resp.messages) || [];
const FLAG = ['mega', 'loudspeaker', 'loudspeaker_with_sound'];
const out = [];
for (const m of msgs) {
  const flagged = (m.reactions || []).some(r => FLAG.indexOf(r.name) !== -1);
  if (flagged && m.ts && !store.fwd[m.ts]) {
    // NOTE: do NOT mark forwarded here — only mark after a successful post (see "Mark forwarded" node),
    // so a failed forward (e.g. #sf-help permission not yet set) retries on the next run instead of being lost.
    const text = String(m.text || '').replace(/\n*_Automated with this <[^>]+>_\s*$/, '').trim();
    const urlMatch = text.match(/<(https?:\/\/[^|>]+)(?:\|[^>]*)?>/);
    const statusUrl = urlMatch ? urlMatch[1] : '';
    const userContent = 'Raw internal alert:\n' + (text || '(no text)') + (statusUrl ? ('\n\nVendor status link: ' + statusUrl) : '');
    out.push({ json: { ts: m.ts, body: { model: 'claude-sonnet-4-6', max_tokens: 400, system: SYSTEM, messages: [{ role: 'user', content: userContent }] } } });
  }
}
return out;

const findItems = $('Find new :mega:').all();
const inItems = $input.all();
const out = [];
for (let i = 0; i < inItems.length; i++) {
  const r = inItems[i].json;
  if (r && r.type === 'error') { throw new Error('Anthropic error: ' + JSON.stringify(r.error || r)); }
  let text = '';
  if (r && Array.isArray(r.content)) { text = r.content.map(c => (c && c.text) || '').join('').trim(); }
  if (!text) { throw new Error('Claude returned no text: ' + JSON.stringify(r).slice(0, 300)); }
  const ts = (findItems[i] && findItems[i].json && findItems[i].json.ts) || '';
  out.push({ json: { message: text, ts: ts } });
}
return out;

// Record dedupe ONLY after the post succeeded (this node runs after 'Post notice').
const extract = $('Extract notice').all();
const store = (typeof $getWorkflowStaticData === 'function') ? $getWorkflowStaticData('global') : this.getWorkflowStaticData('global');
store.fwd = store.fwd || {};
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const ts = extract[i] && extract[i].json && extract[i].json.ts;
  if (ts) { store.fwd[ts] = true; }
}
return items;

